var builder = WebApplication.CreateBuilder(args);

builder.Services.AddApplicationInsightsTelemetry();

// Enable correlation for outgoing HTTP requests
builder.Services.AddHttpClient("orders")
    .AddApplicationInsightsTelemetry();

var app = builder.Build();
app.MapGet("/orders/{id}", async (int id, IHttpClientFactory factory) =>
{
    var client = factory.CreateClient("orders");
    var response = await client.GetAsync($"https://api.example.com/orders/{id}");
    response.EnsureSuccessStatusCode();
    return await response.Content.ReadAsStringAsync();
});

app.Run();

builder.Services.Configure<TelemetryConfiguration>((config) =>
{
    var sampling = new AdaptiveSamplingProcessor
    {
        MaxTelemetryItemsPerSecond = 20,
        MinSamplingPercentage = 5,
        MaxSamplingPercentage = 100,
        ExcludedTypes = "Event;Exception" // always keep exceptions
    };
    config.DefaultTelemetrySink.TelemetryProcessorChainBuilder.Use(sampling);
});

